customCSS:
.t, .history { color: #525252; }
.join { color: #42be65; }
.part, .quit { color: #525252; }
.kick, .error { color: #da1e28; }
.notice { color: #da1e28; }
.action { color: #8a3ffc; }
.mode, .nick, .topic, .server { color: #1192e8; }
.highlight { color: #161616; background-color: #d0e2ff; border-left: 3px solid #8a3ffc; padding-left: 8px; }
.reply { color: #525252; border-left: 2px solid #0f62fe; padding-left: 6px; }
.oper { color: #f2f4f8; background-color: #da1e28; }
.reactions { color: #0f62fe; background-color: #dde1e6; }
.card { background-color: #dde1e6; border-color: #525252; }
.card-title { color: #0f62fe; }
.card-desc { color: #525252; }
.daychange { color: #525252; border-color: #dde1e6; }
